\begin{definition}[Notation: $U_\epsilon$]
\label{def:epsilon-interior-set-notation}
\dcref{appC:C.4-def-1}
\group{Mollification}
For open $U\subset\mathbb R^n$ and $\epsilon>0$, set
\[
U_\epsilon
:=\{x\in U\mid\dist(x,\partial U)>\epsilon\}.
\]
\end{definition}

